        <div class="form-field">
          <fieldset aria-describedby="question-1-help">
            <legend>1. Which of these are primarily used as web browser languages?</legend>
            <p class="help-text" id="question-1-help">Pick all options that are commonly used to build or style pages in the browser.</p>
            <div class="choice-list">
              <label class="choice"><input type="checkbox" name="q1" value="HTML"><span class="choice-text">HTML</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="CSS"><span class="choice-text">CSS</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span class="choice-text">JavaScript</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="COBOL"><span class="choice-text">COBOL</span></label>
            </div>
          </fieldset>
        </div>

