     .help-text {
       margin: 0 0 1rem;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .choice-list {
       display: grid;
       gap: 0.75rem;
     }

     .choice {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
       padding: 0.9rem 1rem;
       border: 1px solid rgba(169, 180, 208, 0.2);
       border-radius: 0.9rem;
       background: rgba(255, 255, 255, 0.02);
       cursor: pointer;
       transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
     }

     .choice:hover {
       transform: translateY(-1px);
       border-color: rgba(124, 156, 255, 0.45);
       background: rgba(124, 156, 255, 0.08);
     }

     .choice input {
       margin-top: 0.15rem;
       inline-size: 1.1rem;
       block-size: 1.1rem;
       accent-color: var(--accent);
       flex-shrink: 0;
     }

     .choice-text {
       color: var(--text);
       line-height: 1.45;
     }

     button {
       justify-self: start;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.4rem;
       font: inherit;
       font-weight: 700;
       color: #09101f;
       background: linear-gradient(135deg, var(--accent-strong), #b7c6ff);
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(124, 156, 255, 0.28);
     }

     button:hover {
       filter: brightness(1.05);
     }

     :focus-visible {
       outline: 3px solid var(--accent-strong);
       outline-offset: 3px;
     }

     .results {
       margin-top: 1.5rem;
       padding: 1rem 1.1rem;
       border-radius: 1rem;
       border: 1px solid rgba(169, 180, 208, 0.2);
       background: rgba(255, 255, 255, 0.03);
     }

     .results[data-tone="success"] {
       border-color: rgba(142, 224, 177, 0.5);
     }

     .results[data-tone="warning"] {
       border-color: rgba(255, 155, 155, 0.4);
     }

     .results h2 {
       margin: 0 0 0.5rem;
       font-size: 1.1rem;
     }

     .results p,
     .results ul {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .results ul {
       margin-top: 0.75rem;
       padding-left: 1.25rem;
     }

     @media (max-width: 40rem) {
       main {
         padding: 1.25rem 0.75rem 2rem;
       }

       .quiz-shell,
       .form-field {
         padding: 1rem;
       }
     }

     @media (forced-colors: active) {
       .quiz-shell,
       .form-field,
       .choice,
       .results {
         border-color: ButtonBorder;
         background: Canvas;
       }

       body {
         background: Canvas;
         color: CanvasText;
       }

       .intro,
       .help-text,
       .results p,
       .results ul {
         color: CanvasText;
       }

       .skip-link,
       button {
         border: 1px solid ButtonBorder;
         background: ButtonFace;
         color: ButtonText;
         box-shadow: none;
       }
     }
   </style>
 </head>
